    // A declInfo describes a package-level const, type, var, or func declaration.
    
    template<typename T> requires gocpp::GoStruct<T>
    declInfo::operator T()
    {
        T result;
        result.file = this->file;
        result.lhs = this->lhs;
        result.vtyp = this->vtyp;
        result.init = this->init;
        result.inherited = this->inherited;
        result.tdecl = this->tdecl;
        result.fdecl = this->fdecl;
        result.deps = this->deps;
        return result;
    }

    template<typename T> requires gocpp::GoStruct<T>
    bool declInfo::operator==(const T& ref) const
    {
        if (file != ref.file) return false;
        if (lhs != ref.lhs) return false;
        if (vtyp != ref.vtyp) return false;
        if (init != ref.init) return false;
        if (inherited != ref.inherited) return false;
        if (tdecl != ref.tdecl) return false;
        if (fdecl != ref.fdecl) return false;
        if (deps != ref.deps) return false;
        return true;
    }

    std::ostream& declInfo::PrintTo(std::ostream& os) const
    {
        os << '{';
        os << "" << file;
        os << " " << lhs;
        os << " " << vtyp;
        os << " " << init;
        os << " " << inherited;
        os << " " << tdecl;
        os << " " << fdecl;
        os << " " << deps;
        os << '}';
        return os;
    }

    std::ostream& operator<<(std::ostream& os, const struct declInfo& value)
    {
        return value.PrintTo(os);
    }

    // hasInitializer reports whether the declared object has an initialization
    // expression or function body.
    bool rec::hasInitializer(declInfo* d)
    {
        return d->init != nullptr || d->fdecl != nullptr && d->fdecl->Body != nullptr;
    }

    // addDep adds obj to the set of objects d's init expression depends on.
    void rec::addDep(declInfo* d, Object obj)
    {
        auto m = d->deps;
        if(m == nullptr)
        {
            m = gocpp::make(gocpp::Tag<gocpp::map<Object, bool>>());
            d->deps = m;
        }
        m[obj] = true;
    }

